// explicit locale(const char* name);

// Explicitly constructs the C locale semantics
std::locale c_locale("C");

// Explicitly constructs the POSIX locale (if available)
std::locale posix_locale("POSIX");

// Prevents unintended implicit conversion:
// std::locale bad_loc = "C"; // Error (or warning) due to explicit
std::string name = c_locale.name();

// Combine existing locale with new facets
std::locale new_loc(c_locale, "en_US.UTF-8");
